import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('RequestContext rename to traceId regression tests', () => {
  test('end-to-end propagation through handle', () => {
    const job = {requestId: 'job-abc', name: 'sample-job'};
    const result = handle('trace-123', 'user-456', job);

    // RequestContext on handle result
    assert.equal(result.context.traceId, 'trace-123');
    assert.equal(result.context.userId, 'user-456');
    assert.equal(result.context.requestId, undefined);
    assert.equal('requestId' in result.context, false);

    // Middleware headers
    assert.equal(result.headers['x-request-id'], 'trace-123');

    // Logging output preserves wire/output key requestId
    assert.equal(result.logs.requestId, 'trace-123');
    assert.equal(result.logs.userId, 'user-456');

    // Response body preserves wire/output key requestId
    assert.equal(result.body.requestId, 'trace-123');

    // Worker job execution preserves Job.requestId and propagates forkContext suffix
    assert.equal(result.body.payload.requestId, 'job-abc');
    assert.equal(result.body.payload.trace, 'trace-123/worker');
    assert.equal(result.body.payload.audit, 'job:job-abc');
    assert.equal(result.body.payload.name, 'sample-job');
  });

  test('context creation and non-mutation in forkContext', () => {
    const root = createContext('trace-root', 'user-primary');
    assert.equal(root.traceId, 'trace-root');
    assert.equal(root.userId, 'user-primary');
    assert.equal('requestId' in root, false);

    const child = forkContext(root, 'stage1');
    assert.equal(root.traceId, 'trace-root');
    assert.equal(child.traceId, 'trace-root/stage1');
    assert.equal(child.userId, 'user-primary');
    assert.equal('requestId' in child, false);

    const grandchild = forkContext(child, 'stage2');
    assert.equal(grandchild.traceId, 'trace-root/stage1/stage2');
    assert.equal(child.traceId, 'trace-root/stage1');
    assert.equal(root.traceId, 'trace-root');
  });

  test('unrelated Job identifier and auditLabel are unchanged', () => {
    const job = {requestId: 'job-999', name: 'background-task'};
    const context = createContext('trace-xyz', 'user-ops');
    const jobDescription = describeJob(job, context);

    assert.equal(jobDescription.requestId, 'job-999');
    assert.equal(jobDescription.trace, 'trace-xyz');
    assert.equal(jobDescription.audit, 'job:job-999');
    assert.equal(jobDescription.name, 'background-task');

    assert.equal(auditLabel('job-999'), 'job:job-999');
  });

  test('traceSummary and plugin consumers preserve output format', () => {
    const context = createContext('trace-plugin', 'user-plugin');
    const summary = traceSummary(context);
    assert.equal(summary.length, 8);
    summary.forEach((item, idx) => {
      assert.equal(item.requestId, 'trace-plugin');
      assert.equal(item.tag, `plugin${idx}`);
      assert.equal(item.user, 'user-plugin');
    });
  });

  test('catalog modules RequestContext and requestId remain unchanged', () => {
    const catalogCtx = {requestId: 'cat-id-1', category: 'books'};
    const catalogRes = record0(catalogCtx);
    assert.equal(catalogRes.requestId, 'cat-id-1');
    assert.equal(catalogRes.category, 'books');
    assert.equal(catalogRes.label, 'record0:cat-id-1');
    assert.equal(audit0('cat-id-1'), 'audit0:cat-id-1');
  });
});

